#!/usr/bin/env python3
"""Apply the reviewed Issue #685 v10.5.4 candidate."""
from __future__ import annotations

import base64
import gzip
import subprocess

PATCH_B64 = """"""

patch = gzip.decompress(base64.b64decode(PATCH_B64))
subprocess.run(
    ["git", "apply", "--whitespace=error-all"],
    input=patch,
    check=True,
)
